userscript.function:

        	const pageInfo = {
        		"PC" : "/Seal/Approval/SealApprovalViewLayout.sux",
        		"MOBILE" : "/Seal/Approval/Mobile/MobileSealApprovalLayout.sux"
        	}

        	const isMobile = /iPhone|iPad|iPod|Android/i.test(window.navigator.userAgent)
        	let deviceType = "";
        	if(isMobile) {
        		deviceType = "MOBILE";
        	} else {
        		deviceType = "PC";
        	}

        	var addHidden = function(form, name, value) {
			    var input = document.createElement('input');
			    input.type = 'hidden';
			    input.name = name;
			    input.value = value;
			    form.insertBefore(input, null);
			}

        	var pid = Sepoa.request.parameterId;
			var form = document.body.appendChild($('<form target="sepoa-link-frame" style="display:none"></form>')[0]);
			addHidden(form, "parameterId", pid);
			addHidden(form, "isPopup", true);
			addHidden(form, "onLink", true);
			addHidden(form, "isRealPopup", true);
			for (var idx in Sepoa.request) {
    			addHidden(form, idx, Sepoa.request[idx]);
			}			

			form.action = pageInfo[deviceType];
			form.method = "post";
			form.submit();
